import { Webhook } from "svix";
import { NextApiRequest, NextApiResponse } from "next";
import { WebhookEvent } from "@clerk/nextjs/server";
import { buffer } from "micro";
import { adapter } from "@/infra/clerk/adapter";

export const config = { api: { bodyParser: false } };

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== "POST") return res.status(405).end();

  const WEBHOOK_SECRET = process.env.CLERK_WEBHOOK_SECRET;
  if (!WEBHOOK_SECRET) {
    console.error("[clerk webhook] CLERK_WEBHOOK_SECRET is not set");
    return res.status(500).json({ error: "Server misconfiguration" });
  }

  const svix_id = req.headers["svix-id"] as string;
  const svix_timestamp = req.headers["svix-timestamp"] as string;
  const svix_signature = req.headers["svix-signature"] as string;

  if (!svix_id || !svix_timestamp || !svix_signature) {
    return res.status(400).json({ error: "Missing svix headers" });
  }

  const rawBody = await buffer(req);
  const wh = new Webhook(WEBHOOK_SECRET);

  let evt: WebhookEvent;
  try {
    evt = wh.verify(rawBody.toString(), {
      "svix-id": svix_id,
      "svix-timestamp": svix_timestamp,
      "svix-signature": svix_signature,
    }) as WebhookEvent;
  } catch (err: unknown) {
    console.error("[clerk webhook] verification failed", err);
    return res.status(400).json({ error: "Bad request" });
  }

  // Handler errors must be 500 so Clerk/svix retries — distinct from 4xx above.
  try {
    switch (evt.type) {
      case "user.created":
      case "user.updated": {
        await adapter.upsertUser({
          id: evt.data.id,
          email: evt.data.email_addresses[0]?.email_address ?? "",
          firstName: evt.data.first_name ?? "",
          lastName: evt.data.last_name ?? "",
          imageUrl: evt.data.image_url ?? "",
        });
        break;
      }
      case "user.deleted": {
        if (evt.data.id) await adapter.deleteUser(evt.data.id);
        break;
      }
    }
    return res.status(200).json({ success: true });
  } catch (err: unknown) {
    console.error("[clerk webhook] handler error", err);
    return res.status(500).json({ error: "Internal error" });
  }
}

