import { db } from "@/lib/db";

export interface ClerkUserData {
  id: string;
  email: string;
  firstName: string;
  lastName: string;
  imageUrl: string;
}

export const adapter = {
  upsertUser: async (data: ClerkUserData) => {
    await db.user.upsert({
      where: { clerkId: data.id },
      update: {
        email: data.email,
        firstName: data.firstName,
        lastName: data.lastName,
        imageUrl: data.imageUrl,
      },
      create: {
        clerkId: data.id,
        email: data.email,
        firstName: data.firstName,
        lastName: data.lastName,
        imageUrl: data.imageUrl,
      },
    });
  },
  deleteUser: async (clerkId: string) => {
    await db.user.delete({ where: { clerkId } });
  },
};

adapters.drizzle-orm:
import { db } from "@/lib/db";
import { users } from "@/lib/schema";
import { eq } from "drizzle-orm";

export interface ClerkUserData {
  id: string;
  email: string;
  firstName: string;
  lastName: string;
  imageUrl: string;
}

export const adapter = {
  upsertUser: async (data: ClerkUserData) => {
    await db
      .insert(users)
      .values({
        clerkId: data.id,
        email: data.email,
        firstName: data.firstName,
        lastName: data.lastName,
        imageUrl: data.imageUrl,
      })
      .onConflictDoUpdate({
        target: users.clerkId,
        set: {
          email: data.email,
          firstName: data.firstName,
          lastName: data.lastName,
          imageUrl: data.imageUrl,
        },
      });
  },
  deleteUser: async (clerkId: string) => {
    await db.delete(users).where(eq(users.clerkId, clerkId));
  },
};

